/** With Presets */
export const WithPresets: Story = {
  name: 'With Presets',
  tags: ['example-with-presets'],
  render: () => WithPresetsExample,
  parameters: {
    docs: {
      source: { language: 'html', code: '<script setup lang="ts">\nimport { ref } from \'vue\';\nimport { PixelDatePicker } from \'@pxlkit/ui-kit-vue\';\n\nconst date = ref<Date | null>(null);\nconst today = new Date();\nconst tomorrow = new Date(today.getFullYear(), today.getMonth(), today.getDate() + 1);\nconst nextWeek = new Date(today.getFullYear(), today.getMonth(), today.getDate() + 7);\nconst presets = [\n  { label: \'Today\', value: today },\n  { label: \'Tomorrow\', value: tomorrow },\n  { label: \'Next week\', value: nextWeek },\n];\n</script>\n\n<template>\n  <PixelDatePicker v-model="date" label="Due date" clearable :presets="presets" />\n</template>' },
    },
  },
};

